function pick(pool, seed, n) {
  const a = pool.slice();
  let s = seed;
  for (let i = a.length - 1; i > 0; i--) {
    s = s * 1103515245 + 12345 & 2147483647;
    const j = s % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a.slice(0, n);
}
